<div class="page-heading text-center"><div class="eyebrow">SECURE ATTENDANCE GATEWAY</div><h1>Dynamic QR Access</h1><p>Token terenkripsi diperbarui setiap 30 detik dan hanya dapat dipakai satu kali.</p></div>
<div class="card qr-card dash-card-interactive mx-auto"><div class="card-body p-4 text-center"><div class="d-flex align-items-center justify-content-between mb-3"><span class="system-status"><span class="live-dot"></span>LIVE TOKEN</span><span class="badge text-bg-primary">ENCRYPTED</span></div><div id="qrcode" class="d-flex justify-content-center bg-white p-3"></div><div class="mt-4"><span class="text-secondary small">TOKEN REFRESH IN</span><div><strong class="fs-3" id="countdown">30</strong> <span class="text-secondary">SEC</span></div></div><div class="small text-secondary">Naikkan kecerahan layar dan hindari pantulan cahaya.</div><div id="qrError" class="text-danger mt-2"></div></div></div>
<?= $this->endSection() ?><?= $this->section('scripts') ?><script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>let timer;async function refresh(){clearInterval(timer);try{const r=await fetch('/api/qr/current'),j=await r.json();if(!r.ok)throw new Error(j.message||'Gagal mengambil QR');document.getElementById('qrcode').innerHTML='';new QRCode(document.getElementById('qrcode'),{text:j.data.token,width:340,height:340,colorDark:'#000000',colorLight:'#ffffff',correctLevel:QRCode.CorrectLevel.M});let left=j.data.ttl;document.getElementById('countdown').textContent=left;timer=setInterval(()=>{left--;document.getElementById('countdown').textContent=left;if(left<=0)refresh()},1000)}catch(e){document.getElementById('qrError').textContent=e.message;setTimeout(refresh,3000)}}refresh();</script><?= $this->endSection() ?>
